import app from 'flarum/forum/app';
import Link from 'flarum/common/components/Link';
import { about, arrivalDate, countryName, progress, shortDate, t } from '../api';
import { Postmark, Stamp } from '../art';
const forumTitle = () => app.forum.attribute('title');

/** Core's avatar markup (picture, or the first letter), from the plain person our API sends. */
export function avatar(person, className = '') {
  if (person?.avatarUrl) return m("img", {
    className: 'Avatar ' + className,
    src: person.avatarUrl,
    alt: "",
    loading: "lazy"
  });
  return m("span", {
    className: 'Avatar SlowMailAvatar ' + className
  }, (person?.displayName || '?').charAt(0).toUpperCase());
}

/** The corner every envelope has: the postmark over the stamp. */
export function Corner(attrs) {
  const {
    letter
  } = attrs;
  return m("div", {
    className: "SlowMailCorner"
  }, m("span", {
    className: "SlowMailCorner-postmark"
  }, Postmark({
    place: letter.postmark,
    date: letter.sentAt,
    forum: forumTitle()
  })), Stamp({
    name: letter.stamp,
    country: letter.origin,
    title: String(t(`stamps.${letter.stamp}`))
  }));
}

/** An envelope in the inbox: who it's from, where from, when it arrived. Opens the letter. */
export function InboxEnvelope(attrs) {
  const {
    letter
  } = attrs;
  const from = letter.with;
  return m(Link, {
    className: 'SlowMailEnvelope' + (letter.read ? '' : ' is-unread'),
    href: app.route('slow-mail.letter', {
      id: letter.id
    })
  }, m("span", {
    className: "SlowMailEnvelope-edge"
  }), m("span", {
    className: "SlowMailEnvelope-top"
  }, m("span", {
    className: "SlowMailEnvelope-return"
  }, letter.postmark || countryName(letter.origin) || forumTitle()), Corner({
    letter
  })), m("span", {
    className: "SlowMailEnvelope-address"
  }, m("span", {
    className: "SlowMailEnvelope-label"
  }, t('envelope.from')), m("span", {
    className: "SlowMailEnvelope-name"
  }, from ? from.displayName : t('envelope.someone')), letter.replyTo ? m("span", {
    className: "SlowMailEnvelope-reply"
  }, t('envelope.reply')) : null, m("span", {
    className: "SlowMailEnvelope-meta"
  }, t('envelope.arrived', {
    date: shortDate(letter.deliveredAt || letter.sentAt)
  }), ' · ', t('envelope.travelled', {
    time: about(letter.travelHours)
  }))), letter.read ? null : m("span", {
    className: "SlowMailEnvelope-new"
  }, t('envelope.new')));
}

/** The path a letter travels, with the envelope where it is now. */
export function JourneyLine(attrs) {
  const {
    letter
  } = attrs;
  const p = progress(letter);
  // A gentle arc, as on an airmail map: one quadratic Bézier, drawn, split at p (de Casteljau) and walked.
  const [x0, y0, cx, cy, x1, y1] = [0, 40, 150, 4, 300, 40];
  const lerp = (a, b) => a + (b - a) * p;
  const [qx, qy] = [lerp(x0, cx), lerp(y0, cy)];
  const [x, y] = [lerp(qx, lerp(cx, x1)), lerp(qy, lerp(cy, y1))];
  const angle = Math.atan2(lerp(cy, y1) - qy, lerp(cx, x1) - qx) * 180 / Math.PI;
  const from = letter.postmark || countryName(letter.origin) || forumTitle();
  const to = letter.destination || letter.with?.displayName || '';
  const at = (px, py) => ({
    left: `${px / 300 * 100}%`,
    top: `${py / 48 * 48}px`
  });
  return m("div", {
    className: 'SlowMailJourney is-' + letter.status
  }, m("svg", {
    className: "SlowMailJourney-map",
    viewBox: "0 0 300 48",
    preserveAspectRatio: "none",
    "aria-hidden": "true"
  }, m("path", {
    d: `M${x0} ${y0} Q${cx} ${cy} ${x1} ${y1}`,
    className: "SlowMailJourney-route"
  }), p > 0 ? m("path", {
    d: `M${x0} ${y0} Q${qx} ${qy} ${x} ${y}`,
    className: "SlowMailJourney-done"
  }) : null), m("span", {
    className: "SlowMailJourney-end",
    style: at(x0, y0)
  }), m("span", {
    className: "SlowMailJourney-end",
    style: at(x1, y1)
  }), letter.status === 'transit' ? m("span", {
    className: "SlowMailJourney-plane",
    style: {
      ...at(x, y),
      transform: `translate(-50%, -50%) rotate(${angle}deg)`
    }
  }, m("svg", {
    viewBox: "0 0 20 14",
    "aria-hidden": "true"
  }, m("rect", {
    x: "0.75",
    y: "0.75",
    width: "18.5",
    height: "12.5",
    rx: "1.5"
  }), m("path", {
    d: "M1 1.5 L10 8 L19 1.5"
  }))) : null, m("div", {
    className: "SlowMailJourney-ends"
  }, m("span", null, from), m("span", null, to)));
}

/** A letter in the outbox: to whom, its journey, and when it gets there (or got there). */
export function OutboxCard(attrs) {
  const {
    letter
  } = attrs;
  const to = letter.with;
  const left = letter.arrivesAt ? (new Date(letter.arrivesAt).getTime() - Date.now()) / 36e5 : 0;
  return m("div", {
    className: 'SlowMailSent is-' + letter.status
  }, m("div", {
    className: "SlowMailSent-head"
  }, avatar(to, 'SlowMailSent-avatar'), m("div", {
    className: "SlowMailSent-to"
  }, m("span", {
    className: "SlowMailSent-label"
  }, t('envelope.to')), m(Link, {
    className: "SlowMailSent-name",
    href: app.route('slow-mail.letter', {
      id: letter.id
    })
  }, to ? to.displayName : t('envelope.someone')), m("span", {
    className: "SlowMailSent-date"
  }, t('outbox.sent', {
    date: shortDate(letter.sentAt)
  }))), Stamp({
    name: letter.stamp,
    country: letter.origin,
    className: 'SlowMailSent-stamp',
    title: String(t(`stamps.${letter.stamp}`))
  })), JourneyLine({
    letter
  }), m("div", {
    className: "SlowMailSent-status"
  }, letter.status === 'transit' ? m("span", null, m("strong", null, t('outbox.arrives_in', {
    time: about(left)
  })), m("span", {
    className: "SlowMailSent-eta"
  }, arrivalDate(letter.arrivesAt))) : letter.status === 'delivered' ? m("span", null, m("strong", null, t('outbox.delivered', {
    date: shortDate(letter.deliveredAt)
  })), m("span", {
    className: "SlowMailSent-eta"
  }, t('envelope.travelled', {
    time: about(letter.travelHours)
  }))) : m("strong", null, t('outbox.returned'))));
}
flarum.reg.add('ernestdefoe-slow-mail', 'forum/components/Envelopes', { avatar: avatar,Corner: Corner,InboxEnvelope: InboxEnvelope,JourneyLine: JourneyLine,OutboxCard: OutboxCard, });